import { Section } from "../../components/ui/Section";
import type { DashboardDictionary } from "../../types/dictionary";
import { PageIntro } from "../shared/PageIntro";
import { ComponentLabDateSection } from "./ComponentLabDateSection";
import { ComponentLabFeedbackSection } from "./ComponentLabFeedbackSection";
import { ComponentLabFormSection } from "./ComponentLabFormSection";
import { ComponentLabFoundationSection } from "./ComponentLabFoundationSection";
import { ComponentLabPositioningSection } from "./ComponentLabPositioningSection";

interface ComponentLabPageProps {
  copy: DashboardDictionary;
}

export const ComponentLabPage = ({ copy }: ComponentLabPageProps) => {
  const lab = copy.componentLab;

  return (
    <>
      <PageIntro id="component-lab-page" copy={copy.pages.componentLab} />
      <Section
        id="component-lab"
        eyebrow={copy.sections.componentLab.eyebrow}
        title={copy.sections.componentLab.title}
        description={copy.sections.componentLab.description}
      >
        <ComponentLabPositioningSection copy={lab} />

        <div className="component-lab__catalog">
          <ComponentLabFoundationSection copy={lab} />
          <ComponentLabFormSection copy={lab} />
          <ComponentLabDateSection copy={lab} />
          <ComponentLabFeedbackSection copy={lab} />
        </div>
      </Section>
    </>
  );
};
