import { useState } from "react";
import {
  Calendar,
  DatePicker,
  MonthPicker,
  MultiDatePicker,
  QuarterRangePicker,
  YearPicker,
} from "../../components/date";
import type {
  CalendarDate,
  CalendarDateRange,
  DateControlLocale,
  YearMonth,
  YearQuarter,
} from "../../components/date";
import { Card } from "../../components/ui/Card";
import type { ComponentLabCopy } from "../../types/dictionary";

interface ComponentLabDateSectionProps {
  copy: ComponentLabCopy;
}

const createTodayValue = (): CalendarDate => {
  const today = new Date();

  return {
    year: today.getFullYear(),
    month: today.getMonth() + 1,
    day: today.getDate(),
  };
};

const createTodayMonth = (): YearMonth => {
  const today = createTodayValue();

  return {
    year: today.year,
    month: today.month,
  };
};

const createTodayQuarter = (): YearQuarter => {
  const today = createTodayValue();

  return {
    year: today.year,
    quarter: Math.ceil(today.month / 3),
  };
};

const createTodayRange = (): CalendarDateRange => {
  const today = createTodayValue();

  return {
    start: today,
    end: today,
  };
};

export const ComponentLabDateSection = ({
  copy,
}: ComponentLabDateSectionProps) => {
  const dateLocale: DateControlLocale = copy.dateControlLocale;
  const [monthValue, setMonthValue] = useState<YearMonth>(createTodayMonth);
  const [quarterValue, setQuarterValue] =
    useState<YearQuarter>(createTodayQuarter);
  const [yearValue, setYearValue] = useState(() => createTodayValue().year);
  const [calendarValue, setCalendarValue] =
    useState<CalendarDate>(createTodayValue);
  const [actionCalendarValue, setActionCalendarValue] =
    useState<CalendarDate>(createTodayValue);
  const [datePickerValue, setDatePickerValue] =
    useState<CalendarDate>(createTodayValue);
  const [calendarRange, setCalendarRange] =
    useState<CalendarDateRange>(createTodayRange);

  return (
    <>
      <Card
        className="component-lab__catalog-card component-lab__catalog-card--full"
        title={copy.datePickerCard.title}
        description={copy.datePickerCard.description}
      >
        <div className="calendar-picker-showcase">
          <MonthPicker
            title="MonthPicker"
            value={monthValue}
            locale={dateLocale}
            onChange={setMonthValue}
          />
          <QuarterRangePicker
            title="QuarterRangePicker"
            value={quarterValue}
            locale={dateLocale}
            onChange={setQuarterValue}
          />
          <YearPicker
            title="YearPicker"
            value={yearValue}
            locale={dateLocale}
            onChange={setYearValue}
          />
        </div>
      </Card>

      <Card
        className="component-lab__catalog-card component-lab__catalog-card--wide"
        title={copy.calendarCard.title}
        description={copy.calendarCard.description}
      >
        <div className="date-calendar-showcase">
          <div className="date-calendar-example">
            <strong>{copy.calendarCard.singleCalendarLabel}</strong>
            <Calendar
              value={calendarValue}
              locale={dateLocale}
              ariaLabel={copy.calendarCard.singleCalendarAriaLabel}
              onChange={setCalendarValue}
            />
          </div>
          <div className="date-calendar-example">
            <strong>{copy.calendarCard.actionCalendarLabel}</strong>
            <Calendar
              value={actionCalendarValue}
              locale={dateLocale}
              ariaLabel={copy.calendarCard.actionCalendarAriaLabel}
              showActions
              onChange={setActionCalendarValue}
            />
          </div>
          <DatePicker
            title={copy.calendarCard.datePickerTitle}
            value={datePickerValue}
            locale={dateLocale}
            onChange={setDatePickerValue}
          />
        </div>
      </Card>

      <Card
        className="component-lab__catalog-card component-lab__catalog-card--full"
        title={copy.multiCalendarCard.title}
        description={copy.multiCalendarCard.description}
      >
        <MultiDatePicker
          title=""
          value={calendarRange}
          locale={dateLocale}
          onChange={setCalendarRange}
        />
      </Card>
    </>
  );
};
