import { useState } from "react";
import { SegmentedControl } from "../../components/form";
import { Card } from "../../components/ui/Card";
import type { ComponentLabCopy } from "../../types/dictionary";

interface ComponentLabFoundationSectionProps {
  copy: ComponentLabCopy;
}

const textSamples = [
  ["xs", "12px"],
  ["sm", "14px"],
  ["md", "16px"],
  ["lg", "20px"],
  ["xl", "28px"],
];

export const ComponentLabFoundationSection = ({
  copy,
}: ComponentLabFoundationSectionProps) => {
  const [activeTab, setActiveTab] = useState("overview");
  const colorSamples = [
    ["default", copy.textCard.colorSamples.default],
    ["muted", copy.textCard.colorSamples.muted],
    ["blue", copy.textCard.colorSamples.blue],
    ["green", copy.textCard.colorSamples.green],
    ["rose", copy.textCard.colorSamples.rose],
  ];
  const tabs = [
    { id: "overview", label: copy.tabsCard.tabs.overview },
    { id: "state", label: copy.tabsCard.tabs.state },
    { id: "a11y", label: copy.tabsCard.tabs.a11y },
  ];
  const roundedTabOptions = tabs.map((tab) => ({
    value: tab.id,
    label: tab.label,
  }));
  const iconButtons = [
    {
      label: copy.buttonCard.iconButtonLabels.search,
      paths: [
        <circle cx="11" cy="11" r="6" key="circle" />,
        <path d="m16 16 4 4" key="line" />,
      ],
    },
    {
      label: copy.buttonCard.iconButtonLabels.add,
      paths: [<path d="M12 5v14" key="v" />, <path d="M5 12h14" key="h" />],
    },
    {
      label: copy.buttonCard.iconButtonLabels.remove,
      paths: [<path d="M5 12h14" key="h" />],
    },
    {
      label: copy.buttonCard.iconButtonLabels.close,
      paths: [
        <path d="m6 6 12 12" key="a" />,
        <path d="m18 6-12 12" key="b" />,
      ],
    },
    {
      label: copy.buttonCard.iconButtonLabels.refresh,
      paths: [
        <path d="M20 11a8.1 8.1 0 0 0-14.9-4.2L3 9" key="a" />,
        <path d="M3 4v5h5" key="b" />,
        <path d="M4 13a8.1 8.1 0 0 0 14.9 4.2L21 15" key="c" />,
        <path d="M16 15h5v5" key="d" />,
      ],
    },
  ];

  return (
    <>
      <Card
        className="component-lab__catalog-card component-lab__catalog-card--full"
        title={copy.textCard.title}
        description={copy.textCard.description}
      >
        <div className="component-lab__demo-stack">
          <div className="component-lab__demo-row">
            {textSamples.map(([size, label]) => (
              <span className={`lab-text lab-text--${size}`} key={size}>
                {label}
              </span>
            ))}
          </div>
          <div className="component-lab__demo-row">
            {colorSamples.map(([color, label]) => (
              <span
                className={`lab-text-color lab-text-color--${color}`}
                key={color}
              >
                {label}
              </span>
            ))}
          </div>
        </div>
      </Card>

      <Card
        className="component-lab__catalog-card component-lab__catalog-card--wide"
        title={copy.buttonCard.title}
        description={copy.buttonCard.description}
      >
        <div className="component-lab__demo-stack">
          <div className="component-lab__subsection">
            <strong>{copy.buttonCard.sizeSection}</strong>
          </div>
          <div className="component-lab__demo-row">
            <button type="button" className="lab-button lab-button--sm">
              sm
            </button>
            <button type="button" className="lab-button">
              md
            </button>
            <button type="button" className="lab-button lab-button--lg">
              lg
            </button>
          </div>
          <div className="component-lab__subsection">
            <strong>{copy.buttonCard.radiusSection}</strong>
          </div>
          <div className="component-lab__demo-row">
            <button type="button" className="lab-button lab-button--square">
              4px
            </button>
            <button type="button" className="lab-button lab-button--rounded">
              8px
            </button>
            <button type="button" className="lab-button lab-button--pill">
              999px
            </button>
          </div>
          <div className="component-lab__subsection">
            <strong>{copy.buttonCard.colorSection}</strong>
          </div>
          <div className="component-lab__demo-row">
            <button type="button" className="lab-button lab-button--blue">
              Blue
            </button>
            <button type="button" className="lab-button lab-button--green">
              Green
            </button>
            <button type="button" className="lab-button lab-button--rose">
              Rose
            </button>
            <button type="button" className="lab-button lab-button--soft">
              Soft
            </button>
            <button type="button" className="lab-button lab-button--dark">
              Dark
            </button>
          </div>
          <div className="component-lab__subsection">
            <strong>{copy.buttonCard.iconButtonSection}</strong>
          </div>
          <div className="component-lab__demo-row">
            {iconButtons.map((item) => (
              <button
                type="button"
                className="lab-icon-button"
                aria-label={item.label}
                key={item.label}
              >
                <svg viewBox="0 0 24 24" aria-hidden="true" focusable="false">
                  {item.paths}
                </svg>
              </button>
            ))}
          </div>
        </div>
      </Card>

      <Card
        className="component-lab__catalog-card"
        title={copy.labelCard.title}
        description={copy.labelCard.description}
      >
        <div className="component-lab__demo-stack">
          <div className="component-lab__subsection">
            <strong>{copy.labelCard.sizeSection}</strong>
          </div>
          <div className="component-lab__demo-row">
            <span className="lab-label lab-label--sm">sm</span>
            <span className="lab-label">Default</span>
            <span className="lab-label lab-label--lg">lg</span>
          </div>
          <div className="component-lab__subsection">
            <strong>{copy.labelCard.colorSection}</strong>
          </div>
          <div className="component-lab__demo-row">
            <span className="lab-label lab-label--blue">Blue</span>
            <span className="lab-label lab-label--green">Green</span>
            <span className="lab-label lab-label--rose">Rose</span>
          </div>
          <div className="component-lab__subsection">
            <strong>{copy.labelCard.radiusSection}</strong>
          </div>
          <div className="component-lab__demo-row">
            <span className="lab-label lab-label--square">Square</span>
            <span className="lab-label lab-label--pill">Pill</span>
          </div>
        </div>
      </Card>

      <Card
        className="component-lab__catalog-card"
        title={copy.filterCard.title}
        description={copy.filterCard.description}
      >
        <div className="component-lab__demo-row">
          {["sm", "md", "lg"].map((size) => (
            <span className={`vetFilter vetFilter--${size}`} key={size}>
              <span className="label">Filter {size}</span>
              <button
                type="button"
                className="button image naked"
                aria-label={copy.filterCard.removeAriaLabel}
              >
                <span className="btnSkin">
                  <span
                    className="icon icon--multiply-outlined"
                    aria-hidden="true"
                  />
                </span>
              </button>
            </span>
          ))}
        </div>
      </Card>

      <Card
        className="component-lab__catalog-card"
        title={copy.tabsCard.title}
        description={copy.tabsCard.description}
      >
        <div className="component-lab__demo-stack">
          <div className="component-lab__subsection">
            <strong>{copy.tabsCard.tabsSection}</strong>
          </div>
          <div
            className="lab-tabs"
            role="tablist"
            aria-label={copy.tabsCard.tabListAriaLabel}
          >
            {tabs.map((tab) => (
              <button
                key={tab.id}
                type="button"
                role="tab"
                aria-selected={activeTab === tab.id}
                className={activeTab === tab.id ? "is-active" : undefined}
                onClick={() => setActiveTab(tab.id)}
              >
                {tab.label}
              </button>
            ))}
          </div>
          <div className="component-lab__subsection">
            <strong>{copy.tabsCard.roundedTabsSection}</strong>
          </div>
          <SegmentedControl
            label={copy.tabsCard.roundedTabsSection}
            value={activeTab}
            options={roundedTabOptions}
            onValueChange={setActiveTab}
          />
        </div>
        <div className="lab-tab-panel" role="tabpanel">
          {copy.tabsCard.selectedTabLabel}:{" "}
          {tabs.find((tab) => tab.id === activeTab)?.label}
        </div>
      </Card>
    </>
  );
};
