import type {
  AppRouteDefinition,
  AppRoutePath,
  NavigationItem,
} from './types/dashboard';
import type { DashboardDictionary } from './types/dictionary';

export const appRoutes: readonly AppRouteDefinition[] = [
  { id: 'home', path: '/', href: '#/' },
  { id: 'charts', path: '/charts', href: '#/charts' },
  { id: 'data-grid', path: '/data-grid', href: '#/data-grid' },
  { id: 'timeline', path: '/timeline', href: '#/timeline' },
  { id: 'api-playground', path: '/api-playground', href: '#/api-playground' },
  { id: 'component-lab', path: '/component-lab', href: '#/component-lab' },
  { id: 'works', path: '/works', href: '#/works' },
];

export const appRoutePaths = appRoutes.map((route) => route.path);

export const isAppRoutePath = (value: string): value is AppRoutePath =>
  appRoutePaths.includes(value as AppRoutePath);

export const createNavigationItems = (
  labels: DashboardDictionary['nav'],
): NavigationItem[] =>
  appRoutes.map((route) => ({
    ...route,
    label: labels[route.id],
  }));
