import type { PropsWithChildren, ReactNode } from 'react';
import { useEffect, useId, useRef, useState } from 'react';

interface PopoverRenderTriggerParams {
  isOpen: boolean;
  panelId: string;
  toggle: () => void;
  close: () => void;
}

interface PopoverProps {
  renderTrigger: (params: PopoverRenderTriggerParams) => ReactNode;
  defaultOpen?: boolean;
  closeOnOutsideClick?: boolean;
  className?: string;
  panelClassName?: string;
  panelRole?: 'dialog' | 'region';
}

export const Popover = ({
  renderTrigger,
  defaultOpen = false,
  closeOnOutsideClick = true,
  className,
  panelClassName,
  panelRole = 'dialog',
  children,
}: PropsWithChildren<PopoverProps>) => {
  const panelId = useId();
  const popoverRef = useRef<HTMLDivElement | null>(null);
  const [isOpen, setIsOpen] = useState(defaultOpen);
  const close = () => setIsOpen(false);
  const toggle = () => setIsOpen((current) => !current);

  useEffect(() => {
    if (!isOpen || !closeOnOutsideClick) {
      return undefined;
    }

    const handlePointerDown = (event: MouseEvent | TouchEvent) => {
      if (
        popoverRef.current &&
        event.target instanceof Node &&
        !popoverRef.current.contains(event.target)
      ) {
        close();
      }
    };

    document.addEventListener('mousedown', handlePointerDown);
    document.addEventListener('touchstart', handlePointerDown);

    return () => {
      document.removeEventListener('mousedown', handlePointerDown);
      document.removeEventListener('touchstart', handlePointerDown);
    };
  }, [closeOnOutsideClick, isOpen]);

  return (
    <div
      ref={popoverRef}
      className={['common-popover', className].filter(Boolean).join(' ')}
    >
      {renderTrigger({
        isOpen,
        panelId,
        toggle,
        close,
      })}
      {isOpen && (
        <div
          id={panelId}
          className={['common-popover__panel', panelClassName]
            .filter(Boolean)
            .join(' ')}
          role={panelRole}
        >
          {children}
        </div>
      )}
    </div>
  );
};
