import type { PropsWithChildren, ReactNode } from 'react';
import { Popover } from '../Popover';

interface TogglePanelProps {
  label: string;
  title?: ReactNode;
  description?: ReactNode;
  defaultOpen?: boolean;
  className?: string;
  buttonClassName?: string;
  panelClassName?: string;
}

export const TogglePanel = ({
  label,
  title,
  description,
  defaultOpen = false,
  className,
  buttonClassName,
  panelClassName,
  children,
}: PropsWithChildren<TogglePanelProps>) => {
  return (
    <Popover
      className={['common-toggle-panel', className].filter(Boolean).join(' ')}
      panelClassName={['common-toggle-panel__body', panelClassName]
        .filter(Boolean)
        .join(' ')}
      panelRole="region"
      defaultOpen={defaultOpen}
      renderTrigger={({ isOpen, panelId, toggle }) => (
        <div className="common-toggle-panel__header">
          <div>
            {title && <strong>{title}</strong>}
            {description && <p>{description}</p>}
          </div>
          <button
            type="button"
            className={['common-toggle-panel__button', buttonClassName]
              .filter(Boolean)
              .join(' ')}
            aria-controls={panelId}
            aria-expanded={isOpen}
            onClick={toggle}
          >
            {label}
          </button>
        </div>
      )}
    >
      {children}
    </Popover>
  );
};
