import { Card } from "../../components/ui/Card";
import type { ComponentLabCopy } from "../../types/dictionary";

interface ComponentLabPositioningSectionProps {
  copy: ComponentLabCopy;
}

export const ComponentLabPositioningSection = ({
  copy,
}: ComponentLabPositioningSectionProps) => (
  <Card
    className="component-lab__positioning"
    title={copy.positioningTitle}
    description={copy.positioningDescription}
  >
    <ul className="component-lab__positioning-list">
      {copy.positioningItems.map((item) => (
        <li key={item}>{item}</li>
      ))}
    </ul>
  </Card>
);
