import type { CSSProperties } from "react";
import { useEffect, useState } from "react";
import { createPortal } from "react-dom";
import { Card } from "../../components/ui/Card";
import { Popover } from "../../components/ui/Popover";
import { TogglePanel } from "../../components/ui/TogglePanel";
import type { ComponentLabCopy } from "../../types/dictionary";

interface ComponentLabFeedbackSectionProps {
  copy: ComponentLabCopy;
}

type SnackbarType = "success" | "error" | "info" | "warning";

const snackbarIcon: Record<SnackbarType, string> = {
  success: "✓",
  error: "!",
  info: "i",
  warning: "▲",
};

export const ComponentLabFeedbackSection = ({
  copy,
}: ComponentLabFeedbackSectionProps) => {
  const [isSnackbarOpen, setIsSnackbarOpen] = useState(false);
  const [snackbarDuration, setSnackbarDuration] = useState(3);
  const [snackbarType, setSnackbarType] = useState<SnackbarType>("success");
  const [snackbarKey, setSnackbarKey] = useState(0);
  const snackbarCopy = copy.snackbarCard.messages;
  const showSnackbar = (type: SnackbarType) => {
    setSnackbarType(type);
    setSnackbarKey((current) => current + 1);
    setIsSnackbarOpen(true);
  };

  useEffect(() => {
    if (!isSnackbarOpen) {
      return undefined;
    }

    const timer = window.setTimeout(
      () => {
        setIsSnackbarOpen(false);
      },
      Math.max(snackbarDuration, 1) * 1000,
    );

    return () => window.clearTimeout(timer);
  }, [isSnackbarOpen, snackbarDuration, snackbarKey]);

  const snackbarRoot =
    typeof document === "undefined"
      ? null
      : document.getElementById("snackbar") ?? document.body;

  return (
    <>
      <Card
        className="component-lab__catalog-card"
        title={copy.snackbarCard.title}
        description={copy.snackbarCard.description}
      >
        <div className="lab-snackbar-controls">
          <div className="lab-snackbar-actions">
            {(["success", "error", "info", "warning"] as const).map((type) => (
              <button
                type="button"
                className="lab-button lab-button--sm"
                key={type}
                onClick={() => showSnackbar(type)}
              >
                {type}
              </button>
            ))}
          </div>
          <label className="lab-snackbar-duration">
            <input
              type="number"
              min="1"
              max="10"
              value={snackbarDuration}
              onChange={(event) =>
                setSnackbarDuration(Number(event.target.value))
              }
            />
            <span>{copy.snackbarCard.durationUnit}</span>
          </label>
        </div>
        <div
          className="lab-snackbar-preview lab-snackbar-preview--success"
          role="status"
        >
          <span className="lab-snackbar__icon" aria-hidden="true">
            {snackbarIcon.success}
          </span>
          <span>{snackbarCopy.success}</span>
        </div>
        {isSnackbarOpen &&
          snackbarRoot &&
          createPortal(
            <div
              key={snackbarKey}
              className={`lab-snackbar lab-snackbar--${snackbarType}`}
              role="status"
              style={
                {
                  "--snackbar-duration": `${Math.max(snackbarDuration, 1)}s`,
                } as CSSProperties
              }
            >
              <span className="lab-snackbar__icon" aria-hidden="true">
                {snackbarIcon[snackbarType]}
              </span>
              <span>{snackbarCopy[snackbarType]}</span>
            </div>,
            snackbarRoot,
          )}
      </Card>

      <Card
        className="component-lab__catalog-card"
        title={copy.tooltipPopoverCard.title}
        description={copy.tooltipPopoverCard.description}
      >
        <div className="tooltip-popover-lab">
          <span className="lab-tooltip">
            <button type="button" className="lab-button">
              Tooltip
            </button>
            <span role="tooltip">{copy.tooltipPopoverCard.tooltipText}</span>
          </span>
          <Popover
            className="lab-popover"
            panelClassName="lab-popover__panel"
            renderTrigger={({ isOpen, panelId, toggle }) => (
              <button
                type="button"
                className={`lab-button ${isOpen ? "lab-button--blue" : "lab-button--soft"}`}
                aria-controls={panelId}
                aria-expanded={isOpen}
                onClick={toggle}
              >
                {isOpen ? "Popover On" : "Popover Off"}
              </button>
            )}
          >
            <strong>{copy.tooltipPopoverCard.popoverTitle}</strong>
            <p>{copy.tooltipPopoverCard.popoverDescription}</p>
          </Popover>
          <TogglePanel
            className="common-toggle-panel--surface lab-toggle-panel"
            panelClassName="common-toggle-panel__dark-list-panel lab-toggle-panel__body"
            label={copy.tooltipPopoverCard.togglePanelLabel}
            title={copy.tooltipPopoverCard.togglePanelTitle}
            description={copy.tooltipPopoverCard.togglePanelDescription}
          >
            <div className="common-toggle-panel__scroll lab-toggle-panel__scroll">
              <div className="common-toggle-panel__pill-list lab-toggle-panel__list">
                {copy.tooltipPopoverCard.togglePanelItems.map((item) => (
                  <span key={item}>{item}</span>
                ))}
              </div>
            </div>
          </TogglePanel>
        </div>
      </Card>
    </>
  );
};
