import { useInfiniteQuery } from '@tanstack/react-query';
import type { MutableRefObject } from 'react';
import { getTourismKeywordSearch } from '../../apis/tourism/tourism';
import type {
  TourismSearchParams,
  TourismSearchResponse,
} from '../../apis/tourism/type';
import { configDefaults } from '../config';
import {
  createAbortRequestError,
  isApiRequestError,
  normalizeApiRequestError,
  withApiRequestMeta,
} from '../../utils/apiError';
import type { ApiRequestMeta } from '../../utils/apiError';

export const tourismSearchQueryKey = (
  keyword: string,
  pageSize: number,
  searchVersion: number,
  failureTestCase: TourismSearchParams['failureTestCase'],
) =>
  [
    'tourismSearch',
    keyword,
    pageSize,
    searchVersion,
    failureTestCase ?? 'none',
  ] as const;

export const useTourismSearchQuery = ({
  keyword,
  pageSize,
  searchVersion,
  requestSequenceRef,
  enabled = true,
  failureTestCase,
}: {
  keyword: string;
  pageSize: number;
  searchVersion: number;
  requestSequenceRef: MutableRefObject<number>;
  enabled?: boolean;
  failureTestCase?: TourismSearchParams['failureTestCase'];
}) =>
  useInfiniteQuery<TourismSearchResponse, Error>({
    queryKey: tourismSearchQueryKey(
      keyword,
      pageSize,
      searchVersion,
      failureTestCase,
    ),
    queryFn: async ({ pageParam, signal }) => {
      const requestPage = typeof pageParam === 'number' ? pageParam : 1;
      const startedAt = new Date().toISOString();
      const startedTime = Date.now();
      const createFallbackRequestMeta = (
        requestId?: number,
      ): ApiRequestMeta => ({
        requestId,
        keyword,
        page: requestPage,
        pageSize,
        startedAt,
        completedAt: new Date().toISOString(),
        latencyMs: Date.now() - startedTime,
      });

      try {
        const response = await getTourismKeywordSearch({
          keyword,
          page: requestPage,
          pageSize,
          signal,
          failureTestCase,
        });

        if (signal.aborted) {
          throw createAbortRequestError(
            'The tourism search request was canceled before it completed.',
            createFallbackRequestMeta(),
          );
        }

        requestSequenceRef.current += 1;

        return {
          ...response,
          requestId: requestSequenceRef.current,
        };
      } catch (error) {
        if (signal.aborted) {
          throw error;
        }

        requestSequenceRef.current += 1;

        const normalizedError = isApiRequestError(error)
          ? error
          : normalizeApiRequestError(error);
        const fallbackRequestMeta = createFallbackRequestMeta(
          requestSequenceRef.current,
        );
        const requestMeta = {
          ...fallbackRequestMeta,
          ...normalizedError.requestMeta,
          requestId: requestSequenceRef.current,
          keyword: normalizedError.requestMeta?.keyword ?? keyword,
          page: normalizedError.requestMeta?.page ?? requestPage,
          pageSize: normalizedError.requestMeta?.pageSize ?? pageSize,
        };

        throw withApiRequestMeta(normalizedError, requestMeta);
      }
    },
    initialPageParam: 1,
    getNextPageParam: (lastPage) =>
      lastPage.data.hasNextPage ? lastPage.data.page + 1 : undefined,
    enabled: enabled && keyword.length > 0,
    ...configDefaults,
  });
