import type { CSSProperties } from "react";
import { useState } from "react";
import {
  CheckboxField,
  FormControl,
  NumberField,
  RadioGroup,
  SearchField,
  SelectField,
  TextareaField,
  TextField,
} from "../../components/form";
import { Card } from "../../components/ui/Card";
import type { ComponentLabCopy } from "../../types/dictionary";

interface ComponentLabFormSectionProps {
  copy: ComponentLabCopy;
}

const TEXT_COUNTER_LIMIT = 200;
const TEXTAREA_COUNTER_LIMIT = 200;

const switchSizeOptions = [
  { size: "xs", color: "var(--blue)" },
  { size: "sm", color: "var(--blue)" },
  { size: "md", color: "var(--blue)" },
  { size: "default", color: "var(--blue)" },
  { size: "lg", color: "var(--blue)" },
  { size: "xl", color: "var(--blue)" },
];

const switchToneOptions = [
  { label: "Default", color: "var(--blue)" },
  { label: "Green", color: "var(--green)" },
  { label: "Rose", color: "var(--rose)" },
];

const renderSearchIcon = () => (
  <svg viewBox="0 0 24 24" aria-hidden="true" focusable="false">
    <circle cx="11" cy="11" r="6" />
    <path d="m16 16 4 4" />
  </svg>
);

export const ComponentLabFormSection = ({
  copy,
}: ComponentLabFormSectionProps) => {
  const [keyword, setKeyword] = useState("");
  const [fieldName, setFieldName] = useState("");
  const [useTextValue, setUseTextValue] = useState("");
  const [description, setDescription] = useState("");
  const [score, setScore] = useState(80);
  const [status, setStatus] = useState(copy.selectOptions[0]?.value ?? "");
  const [isConfirmed, setIsConfirmed] = useState(true);
  const [isAutoSaveEnabled, setIsAutoSaveEnabled] = useState(true);
  const [notificationChannel, setNotificationChannel] = useState(
    copy.radioOptions[0]?.value ?? "",
  );
  const textareaDisabledValue = copy.fieldCard.disabledTextareaValue;
  const useTextCounter = `${useTextValue.length}/${TEXT_COUNTER_LIMIT}`;
  const textareaCounter = `${description.length}/${TEXTAREA_COUNTER_LIMIT}`;
  const disabledTextareaCounter = `${textareaDisabledValue.length}/${TEXTAREA_COUNTER_LIMIT}`;
  const switchSampleLabel = isAutoSaveEnabled
    ? copy.choiceCard.switchOnAriaLabel
    : copy.choiceCard.switchOffAriaLabel;

  return (
    <>
      <Card
        className="component-lab__catalog-card component-lab__catalog-card--full"
        title={copy.fieldCard.title}
        description={copy.fieldCard.description}
      >
        <div className="component-lab__input-catalog">
          <div className="component-lab__field-surface">
            <div className="component-lab__subsection">
              <strong>{copy.fieldCard.commonFieldsTitle}</strong>
            </div>
            <FormControl className="component-lab__form-stack">
              <SearchField
                label={copy.fields.keywordLabel}
                value={keyword}
                placeholder={copy.fields.keywordPlaceholder}
                helperText={copy.fields.keywordHelper}
                onChange={(event) => setKeyword(event.target.value)}
              />
              <TextField
                label={copy.fields.textLabel}
                value={fieldName}
                placeholder={copy.fields.textPlaceholder}
                helperText={copy.fields.textHelper}
                onChange={(event) => setFieldName(event.target.value)}
              />
              <NumberField
                label={copy.fields.numberLabel}
                value={score}
                min="0"
                max="100"
                helperText={copy.fields.numberHelper}
                onChange={(event) => setScore(Number(event.target.value))}
              />
              <SelectField
                label={copy.fields.selectLabel}
                value={status}
                options={copy.selectOptions}
                helperText={copy.fields.selectHelper}
                onValueChange={setStatus}
              />

              <TextField
                label={copy.fields.disabledLabel}
                value={copy.fields.disabledValue}
                helperText={copy.fields.disabledHelper}
                disabled
                readOnly
              />
              <TextField
                label={copy.fields.requiredLabel}
                value=""
                placeholder={copy.fields.requiredPlaceholder}
                error={copy.fields.requiredError}
                required
                readOnly
              />
            </FormControl>
          </div>

          <div className="input-spec">
            <div className="component-lab__subsection">
              <strong>Input</strong>
            </div>
            <div className="input-spec__group">
              <strong>Default : height(28px)</strong>
              <div className="input-spec__row">
                <span className="lab-input">
                  <input placeholder={copy.fieldCard.inputPlaceholder} />
                </span>
                <span className="lab-input is-on">
                  <input value="class= on" readOnly />
                </span>
                <span className="lab-input is-focused">
                  <input value="class=focused" readOnly />
                </span>
                <span className="lab-input lab-input--wide">
                  <input placeholder={copy.fieldCard.inputPlaceholder} />
                </span>
              </div>
            </div>
            <div className="input-spec__group">
              <strong>Disabled</strong>
              <div className="input-spec__row">
                <span className="lab-input is-disabled">
                  <input value="class='disabled'" disabled />
                </span>
                <span className="lab-input lab-input--with-button is-disabled">
                  <input value="class='disabled'" disabled />
                  <button
                    type="button"
                    aria-label={copy.fieldCard.clearAriaLabel}
                    disabled
                  >
                    ×
                  </button>
                  <button
                    type="button"
                    aria-label={copy.fieldCard.searchAriaLabel}
                    disabled
                  >
                    {renderSearchIcon()}
                  </button>
                </span>
              </div>
            </div>
            <div className="input-spec__group">
              <strong>Use Button</strong>
              <div className="input-spec__row">
                <span className="lab-input lab-input--with-button">
                  <input placeholder={copy.fieldCard.inputPlaceholder} />
                  <button
                    type="button"
                    aria-label={copy.fieldCard.searchAriaLabel}
                  >
                    {renderSearchIcon()}
                  </button>
                </span>
                <span className="lab-input lab-input--with-button">
                  <input placeholder={copy.fieldCard.inputPlaceholder} />
                  <button
                    type="button"
                    aria-label={copy.fieldCard.clearAriaLabel}
                  >
                    ×
                  </button>
                  <button
                    type="button"
                    aria-label={copy.fieldCard.searchAriaLabel}
                  >
                    {renderSearchIcon()}
                  </button>
                </span>
              </div>
            </div>
            <div className="input-spec__group">
              <strong>Use Button : RTL</strong>
              <div className="input-spec__row">
                <span className="lab-input lab-input--with-button lab-input--rtl">
                  <button
                    type="button"
                    aria-label={copy.fieldCard.searchAriaLabel}
                  >
                    {renderSearchIcon()}
                  </button>
                  <input placeholder={copy.fieldCard.inputPlaceholder} />
                </span>
                <span className="lab-input lab-input--with-button lab-input--rtl">
                  <button
                    type="button"
                    aria-label={copy.fieldCard.searchAriaLabel}
                  >
                    {renderSearchIcon()}
                  </button>
                  <button
                    type="button"
                    aria-label={copy.fieldCard.clearAriaLabel}
                  >
                    ×
                  </button>
                  <input placeholder={copy.fieldCard.inputPlaceholder} />
                </span>
              </div>
            </div>
            <div className="input-spec__group">
              <strong>Use Text</strong>
              <span className="lab-input lab-input--with-text">
                <input
                  value={useTextValue}
                  maxLength={TEXT_COUNTER_LIMIT}
                  placeholder={copy.fieldCard.inputPlaceholder}
                  onChange={(event) =>
                    setUseTextValue(
                      event.target.value.slice(0, TEXT_COUNTER_LIMIT),
                    )
                  }
                />
                <span className="lab-counter lab-counter--sm">
                  {useTextCounter}
                </span>
              </span>
            </div>
            <div className="input-spec__group">
              <strong>Size : sm(22px)</strong>
              <div className="input-spec__row">
                <span className="lab-input lab-input--sm">
                  <input placeholder={copy.fieldCard.inputPlaceholder} />
                </span>
                <span className="lab-input lab-input--sm lab-input--with-button">
                  <input placeholder={copy.fieldCard.inputPlaceholder} />
                  <button
                    type="button"
                    aria-label={copy.fieldCard.clearAriaLabel}
                  >
                    ×
                  </button>
                  <button
                    type="button"
                    aria-label={copy.fieldCard.searchAriaLabel}
                  >
                    {renderSearchIcon()}
                  </button>
                </span>
              </div>
            </div>
          </div>

          <div className="textarea-spec">
            <div className="component-lab__subsection">
              <strong>Textarea</strong>
            </div>
            <TextareaField
              label={copy.fields.textareaLabel}
              value={description}
              maxLength={TEXTAREA_COUNTER_LIMIT}
              placeholder={copy.fields.textareaPlaceholder}
              helperText={copy.fields.textareaHelper}
              rows={4}
              counterText={textareaCounter}
              onChange={(event) =>
                setDescription(
                  event.target.value.slice(0, TEXTAREA_COUNTER_LIMIT),
                )
              }
            />
            <TextareaField
              label={copy.fieldCard.disabledTextareaLabel}
              value={textareaDisabledValue}
              rows={4}
              counterText={disabledTextareaCounter}
              disabled
              readOnly
            />
          </div>
        </div>
      </Card>

      <Card
        className="component-lab__catalog-card component-lab__catalog-card--wide"
        title={copy.choiceCard.title}
        description={copy.choiceCard.description}
      >
        <FormControl className="component-lab__form-stack">
          <div className="component-lab__control-row">
            <CheckboxField
              label={copy.fields.checkboxLabel}
              helperText={copy.fields.checkboxHelper}
              checked={isConfirmed}
              onChange={(event) => setIsConfirmed(event.target.checked)}
            />
            <CheckboxField
              label={copy.choiceCard.disabledCheckboxLabel}
              checked
              disabled
              helperText={copy.choiceCard.disabledCheckboxHelper}
              readOnly
            />
          </div>
          <div className="component-lab__control-row">
            <label className="lab-round-check">
              <input type="checkbox" defaultChecked />
              <span aria-hidden="true" />
              {copy.choiceCard.roundCheckboxLabel}
            </label>
          </div>
          <div className="component-lab__control-row">
            <RadioGroup
              legend={copy.fields.radioLegend}
              name="component-lab-notification"
              value={notificationChannel}
              options={copy.radioOptions}
              helperText={copy.fields.radioHelper}
              onChange={setNotificationChannel}
            />
          </div>
          <div className="component-lab__subsection">
            <strong>{copy.choiceCard.switchDefaultSection}</strong>
          </div>
          <div className="lab-switch-showcase">
            <label
              className={`lab-toggle-pill lab-toggle-pill--sample${isAutoSaveEnabled ? " is-on" : ""}`}
              aria-label={switchSampleLabel}
              style={{ "--switch-on-color": "var(--blue)" } as CSSProperties}
            >
              <input
                type="checkbox"
                checked={isAutoSaveEnabled}
                onChange={(event) =>
                  setIsAutoSaveEnabled(event.target.checked)
                }
              />
              <span aria-hidden="true" />
              <em>{isAutoSaveEnabled ? "On" : "Off"}</em>
            </label>
            <label className="lab-toggle-pill is-disabled">
              <input type="checkbox" disabled />
              <span aria-hidden="true" />
              <em>Disabled</em>
            </label>
          </div>
          <div className="component-lab__subsection">
            <strong>{copy.choiceCard.switchSizeSection}</strong>
          </div>
          <div
            className="lab-switch-size-row"
            aria-label={copy.choiceCard.switchSizeAriaLabel}
          >
            {switchSizeOptions.map((option) => (
              <label
                className={`lab-switch lab-switch--${option.size}`}
                key={option.size}
                style={{ "--switch-on-color": option.color } as CSSProperties}
              >
                <input
                  type="checkbox"
                  aria-label={`${option.size} ${copy.choiceCard.switchAriaSuffix}`}
                  defaultChecked
                />
                <span aria-hidden="true" />
              </label>
            ))}
          </div>
          <div className="component-lab__subsection">
            <strong>{copy.choiceCard.switchColorSection}</strong>
          </div>
          <div
            className="lab-switch-size-row"
            aria-label={copy.choiceCard.switchColorAriaLabel}
          >
            {switchToneOptions.map((option) => (
              <label
                className="lab-switch lab-switch--default"
                key={option.label}
                style={{ "--switch-on-color": option.color } as CSSProperties}
              >
                <input type="checkbox" defaultChecked />
                <span aria-hidden="true" />
                <em>{option.label}</em>
              </label>
            ))}
          </div>
        </FormControl>
      </Card>
    </>
  );
};
